'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];document.documentElement.classList.add('js');
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x)),mix=(a,b,t)=>a+(b-a)*t,smooth=x=>{x=clamp(x);return x*x*(3-2*x)};
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,playing=false,filmStart=0,frameId=0,last=0,p=0,mouse={x:0,y:0},follow={x:0,y:0},scene=-1,previousFocus=null;
function motionLabel(){document.body.classList.toggle('reduced',reduced);$('#motion').textContent=reduced?'Ativar movimento':'Reduzir movimento';$('#motion').setAttribute('aria-pressed',String(reduced))}motionLabel();
$('#motion').onclick=()=>{reduced=!reduced;motionLabel();render()};
function stopFilm(){playing=false;$('#film-controls').hidden=true;$('#film').innerHTML='<span class="play-icon">▶</span> Assistir à experiência <small>35 segundos</small>'}
$('#film').onclick=()=>{if(playing){stopFilm();return}playing=true;filmStart=performance.now();window.scrollTo({top:0,behavior:'instant'});$('#film-controls').hidden=false;$('#film').innerHTML='<span class="play-icon">Ⅱ</span> Experiência em reprodução';render()};$('#pause').onclick=stopFilm;
['wheel','touchstart'].forEach(e=>window.addEventListener(e,()=>{if(playing)stopFilm()},{passive:true}));window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','PageUp','PageDown','Home','End',' '].includes(e.key))stopFilm()});
function extent(){return Math.max(1,$('.story').offsetHeight-$('.sticky').offsetHeight)}
$$('[data-chapter]').forEach(b=>b.onclick=()=>{stopFilm();window.scrollTo({top:extent()*(+b.dataset.chapter/3.5),behavior:reduced?'instant':'smooth'});render()});
const labels=['UMA IDEIA. INFINITAS POSSIBILIDADES.','DESKTOP & MOBILE. A MESMA IDENTIDADE.','DA SOLICITAÇÃO À ORGANIZAÇÃO.','AUTOMAÇÃO COM CONTATO HUMANO.'];
function setScene(index){if(index===scene)return;scene=index;$$('.narrative').forEach((n,i)=>{n.classList.toggle('active',i===index);n.inert=i!==index;n.setAttribute('aria-hidden',String(i!==index))});$$('[data-chapter]').forEach((n,i)=>{n.classList.toggle('selected',i===index);n.setAttribute('aria-current',i===index?'step':'false')});$('.website').classList.toggle('visible',index<2);$('.dashboard').classList.toggle('visible',index===2);$('.messenger').classList.toggle('visible',index===3);$('#address').textContent=index<2?'odontoviva.exemplo':index===2?'flow.exemplo / painel':'bgtech.exemplo / atendimento';$('#device-label').textContent=labels[index];}
function render(){if(!frameId)frameId=requestAnimationFrame(tick)}
function tick(time){frameId=0;let dt=Math.min(time-last||16,48);last=time;if(playing){let f=clamp((time-filmStart)/35000);window.scrollTo({top:f*(document.documentElement.scrollHeight-innerHeight),behavior:'instant'});if(f===1)stopFilm()}
let target=clamp(scrollY/extent()*3.5,0,3.5);p=reduced?target:mix(p,target,1-Math.exp(-dt/110));setScene(clamp(Math.floor(p+.15),0,3));follow.x=mix(follow.x,mouse.x,.045);follow.y=mix(follow.y,mouse.y,.045);
const mobile=innerWidth<=760;let entrance=smooth(time/1500);let phoneShow=smooth((p-.55)/.38)*(1-smooth((p-1.65)/.3));let zoom=smooth((p-1.32)/.35)*(1-smooth((p-1.83)/.28));let turn=scene===3?-5:scene===2?-9:-22+smooth(p)*10;
if(reduced){phoneShow=scene===1?1:0;zoom=0;turn=-8}
let sc=(mobile?.94:.85)+zoom*.18;let ry=turn+(reduced?0:follow.x*3),rx=5+(reduced?0:follow.y*2);let rz=mix(-3,0,smooth(p));let dy=reduced?0:(1-entrance)*32;
$('.laptop').style.transform=`translate3d(${-zoom*45}px,${dy}px,${zoom*65}px) rotateX(${rx}deg) rotateY(${ry}deg) rotateZ(${rz}deg) scale(${sc})`;
$('.phone').style.opacity=String(phoneShow);$('.phone').style.transform=`translate3d(${(1-phoneShow)*95}px,${(1-phoneShow)*65}px,140px) rotateY(${-15+phoneShow*10}deg) rotateZ(${4*phoneShow}deg)`;
$$('.messenger .bubble').forEach((b,i)=>{let vis=reduced?(scene===3?1:0):smooth((p-2.8-i*.12)/.17);b.style.opacity=vis;b.style.transform=`translateY(${(1-vis)*15}px)`});
let settling=Math.abs(p-target)>.002||Math.abs(mouse.x-follow.x)>.005||Math.abs(mouse.y-follow.y)>.005;
if(!document.hidden&&(playing||(!reduced&&(settling||time<1600))))render();}
addEventListener('scroll',render,{passive:true});addEventListener('resize',render);addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&!reduced){mouse.x=(e.clientX/innerWidth-.5)*2;mouse.y=(e.clientY/innerHeight-.5)*2;render()}},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopFilm();else render()});
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}),{threshold:.1});$$('.reveal').forEach(n=>observer.observe(n))}else $$('.reveal').forEach(n=>n.classList.add('in-view'));
const dialog=$('#demo-dialog');$('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus()});
const bookings=[];
$$('[data-demo]').forEach(b=>b.onclick=()=>openDemo(b.dataset.demo));
function openDemo(type){stopFilm();previousFocus=document.activeElement;$('#dialog-title').textContent={site:'Aurora · Site institucional',agenda:'Flow · Agendamento',chat:'BGTech · Atendimento simulado'}[type];$('#demo-body').replaceChildren();if(type==='site')siteDemo();if(type==='agenda')agendaDemo();if(type==='chat')chatDemo();document.body.style.overflow='hidden';dialog.showModal()}
function siteDemo(){const body=$('#demo-body');body.innerHTML='<div class="demo-tabs" role="group" aria-label="Páginas do site"><button data-page="0">Início</button><button data-page="1">O estúdio</button><button data-page="2">Contato</button></div><div class="site-demo" aria-live="polite"></div><p class="demo-note">Estúdio fictício. Este exemplo mostra a navegação entre as páginas de um site institucional.</p>';const pages=[`<div class="architecture"><div class="arch"></div><div class="sun"></div><div class="plinth"></div><div class="sphere"></div></div><small>AURORA / ARQUITETURA</small><h3>Espaços para<br>viver melhor.</h3><p>Projetos que acolhem a rotina e valorizam os pequenos momentos. Conheça a proposta deste estúdio conceitual.</p>`,`<small>O ESTÚDIO</small><h3>O essencial<br>tem seu lugar.</h3><p>Uma demonstração de como apresentar a identidade de uma empresa: o que ela faz, como trabalha e o que valoriza.</p><p>Materiais naturais, luz e proporções equilibradas orientam este conceito visual.</p>`,`<small>VAMOS CONVERSAR</small><h3>Seu espaço.<br>Uma nova história.</h3><p>Em um projeto real, esta página pode reunir formulário, localização e canais de atendimento.</p><p>Gostou deste exemplo? O botão abaixo abre o contato real da BGTech.</p><a class="action" target="_blank" rel="noopener" href="https://wa.me/5511920193443?text=Ol%C3%A1%21%20Gostei%20da%20demonstra%C3%A7%C3%A3o%20Aurora%20e%20quero%20um%20site.">Conversar com a BGTech ↗</a>`];function select(i){$('.site-demo').innerHTML=pages[i];$$('[data-page]').forEach(b=>{b.classList.toggle('chosen',+b.dataset.page===i);b.setAttribute('aria-pressed',String(+b.dataset.page===i))})}$$('[data-page]').forEach(b=>b.onclick=()=>select(+b.dataset.page));select(0)}
function agendaDemo(){const body=$('#demo-body');body.innerHTML='<div class="agenda-demo"><form class="demo-form"><label>Nome de exemplo<input id="booking-name" name="name" maxlength="40" value="Ana Costa" autocomplete="off" required></label><label>Serviço<select id="booking-service"><option>Apresentação de projeto</option><option>Planejamento de site</option><option>Conversa sobre automação</option></select></label><label>Horário<select id="booking-time"><option>09:00</option><option>10:30</option><option>14:30</option><option>16:00</option></select></label><button class="action" type="submit">Confirmar agendamento</button><p class="feedback" role="status"></p></form><div class="agenda-list"><h3>Agenda demonstrativa</h3><div id="bookings"></div></div></div><p class="demo-note">Use um nome fictício. Os agendamentos existem apenas enquanto esta página está aberta; não há integração com uma agenda real.</p>';function paint(){const list=$('#bookings');list.replaceChildren();if(!bookings.length){const n=document.createElement('p');n.className='empty-note';n.textContent='Escolha um horário e veja o agendamento aparecer aqui.';list.append(n)}for(const b of bookings){const item=document.createElement('div');item.className='booking';const title=document.createElement('strong');title.textContent=b.time+' · '+b.name;const note=document.createElement('small');note.textContent=b.service+' · Confirmado';item.append(title,note);list.append(item)}}$('.demo-form').onsubmit=e=>{e.preventDefault();const name=$('#booking-name').value.trim(),time=$('#booking-time').value,service=$('#booking-service').value;if(!name){$('.feedback').textContent='Informe um nome de exemplo.';return}if(bookings.some(b=>b.time===time)){$('.feedback').textContent='Esse horário já foi escolhido. Experimente outro.';return}bookings.push({name,time,service});bookings.sort((a,b)=>a.time.localeCompare(b.time));paint();$('.feedback').textContent='Agendamento confirmado! Ele já aparece no painel.'};paint()}

render();
